import{_ as e,o as i,c as l,a0 as o}from"./chunks/framework.jwovEGr5.js";const c=JSON.parse('{"title":"嵌入式开发","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"概念学习/嵌入式开发.md","filePath":"概念学习/嵌入式开发.md"}'),r={name:"概念学习/嵌入式开发.md"};function t(p,a,h,n,d,s){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="嵌入式开发" tabindex="-1">嵌入式开发 <a class="header-anchor" href="#嵌入式开发" aria-label="Permalink to &quot;嵌入式开发&quot;">​</a></h1><h2 id="什么是嵌入式系统-开发" tabindex="-1">什么是嵌入式系统/开发 <a class="header-anchor" href="#什么是嵌入式系统-开发" aria-label="Permalink to &quot;什么是嵌入式系统/开发&quot;">​</a></h2><h3 id="嵌入式系统" tabindex="-1">嵌入式系统 <a class="header-anchor" href="#嵌入式系统" aria-label="Permalink to &quot;嵌入式系统&quot;">​</a></h3><p>把专用计算机硬件（芯片）嵌入到各类设备内部，只完成单一/特定功能、软硬件高度绑定、资源有限的专用计算机系统。</p><h3 id="嵌入式开发-1" tabindex="-1">嵌入式开发 <a class="header-anchor" href="#嵌入式开发-1" aria-label="Permalink to &quot;嵌入式开发&quot;">​</a></h3><p>就是为这类专用设备编写<a href="#底层驱动">底层驱动</a>、<a href="#操作系统">操作系统</a>、业务程序，让硬件按照需求稳定运行的全过程。</p><blockquote><p>不是电脑、手机这种通用设备，而是藏在各种电器、器械里的“微型小电脑”，给它写程序就是嵌入式开发。</p></blockquote><h2 id="嵌入式系统典型设备" tabindex="-1">嵌入式系统典型设备 <a class="header-anchor" href="#嵌入式系统典型设备" aria-label="Permalink to &quot;嵌入式系统典型设备&quot;">​</a></h2><ol><li>消费电子</li></ol><p>智能手表、蓝牙耳机、路由器、摄像头、空调、电视、扫地机器人、电饭煲、充电桩</p><ol start="2"><li>工业设备</li></ol><p>PLC工控板、变频器、传感器、工业机器人、仪器仪表</p><ol start="3"><li>汽车电子</li></ol><p>车载中控、<a href="#esp">ESP</a>、自动驾驶MCU、电池管理BMS、仪表盘</p><ol start="4"><li>物联网IoT</li></ol><p>WiFi模组、蓝牙模块、门禁、智能传感器、快递柜</p><h2 id="嵌入式开发两大分支" tabindex="-1">嵌入式开发两大分支 <a class="header-anchor" href="#嵌入式开发两大分支" aria-label="Permalink to &quot;嵌入式开发两大分支&quot;">​</a></h2><h3 id="单片机开发-裸机-rtos-低端小型设备" tabindex="-1">单片机开发（裸机/RTOS，低端小型设备） <a class="header-anchor" href="#单片机开发-裸机-rtos-低端小型设备" aria-label="Permalink to &quot;单片机开发（裸机/RTOS，低端小型设备）&quot;">​</a></h3><p>硬件：8位/32位单片机（STM32、51、PIC、ESP32）</p><p>特点：资源极小（几KB内存），无完整Linux系统</p><p><strong>工作内容：</strong></p><p>直接操作寄存器、写<a href="#底层驱动">底层驱动</a>（LED、按键、串口、I2C、SPI）</p><p>裸机编程/小型实时操作系统FreeRTOS、RT-Thread</p><p>控制电机、传感器、蓝牙/WiFi通信</p><h3 id="linux嵌入式开发-高端复杂设备" tabindex="-1">Linux嵌入式开发（高端复杂设备） <a class="header-anchor" href="#linux嵌入式开发-高端复杂设备" aria-label="Permalink to &quot;Linux嵌入式开发（高端复杂设备）&quot;">​</a></h3><p>硬件：ARM开发板（瑞芯微、全志、NXP、树莓派），内存百MB级以上</p><p>分层开发，岗位细分：</p><p>底层驱动开发：修改内核、写设备驱动（屏幕、网卡、USB）、移植内核</p><p>系统移植：裁剪Linux内核、制作根文件系统、搭建交叉编译环境、Bootloader（U-Boot）</p><p>应用开发：C/C++写业务程序、音视频、MQTT物联网、QT界面、网络服务</p><p>安卓嵌入式：车载Android、平板工控机</p><h3 id="主要编程语言" tabindex="-1">主要编程语言 <a class="header-anchor" href="#主要编程语言" aria-label="Permalink to &quot;主要编程语言&quot;">​</a></h3><ol><li><p>C语言（绝对核心）：<a href="#底层驱动">底层驱动</a>、单片机、Linux内核标配</p></li><li><p>C++：大型Linux应用、QT界面、音视频项目</p></li><li><p>Python：Linux上层快速验证、物联网脚本（底层不用）</p></li><li><p>汇编：极少用，仅Bootloader、内核启动底层优化</p></li><li><p>Rust：新兴，用于高安全车载、工控嵌入式</p></li></ol><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><h3 id="底层驱动" tabindex="-1">底层驱动 <a class="header-anchor" href="#底层驱动" aria-label="Permalink to &quot;底层驱动&quot;">​</a></h3><p>底层驱动是程序以访问底层硬件的形式实现人机交互，驱动程序和应用程序之间需要实现相应的信息交互，一方面，应用程序通过对驱动程序发送相应的指令，实现硬件控制的动作指令，另一方面，驱动程序将硬件读写的状态、从硬件上获得的数据传送给应用程序，实现应用程序与驱动程序间的交互。</p><p>总结</p><p>底层驱动是操作系统和硬件之间的“翻译官+连接器”，直接和硬件寄存器、电路通信，属于最贴近硬件的软件程序，是硬件能被CPU、系统识别并使用的基础底层代码</p><h3 id="操作系统" tabindex="-1">操作系统 <a class="header-anchor" href="#操作系统" aria-label="Permalink to &quot;操作系统&quot;">​</a></h3><p>操作系统是一种内置的程序，用来协作计算机的各种硬件，以与用户进行交互。常见有Windows，macOS和开源的Linux、华为鸿蒙系统。</p><p>是管理电脑/手机所有硬件、调度软件、给程序提供运行环境的核心系统软件，是硬件和应用软件中间的大总管。</p><p>核心功能</p><ol><li>硬件资源管理</li><li>承接底层驱动，统一硬件接口</li><li>进程与软件调度</li><li>人机交互</li></ol><p>驱动是操作系统用来操控硬件的“工具”，操作系统是整体管理平台，可以加载、卸载驱动</p><h3 id="esp" tabindex="-1">ESP <a class="header-anchor" href="#esp" aria-label="Permalink to &quot;ESP&quot;">​</a></h3><p>ESP是上海乐鑫公司出品的Wi-Fi+蓝牙物联网主控芯片，内置处理器、无线射频、GPIO外设，属于片上系统SoC，可以直接写底层驱动、跑RTOS、Arduino程序，做智能家居、传感器联网、无线控制。</p>',46)])])}const P=e(r,[["render",t]]);export{c as __pageData,P as default};
